880	const DX=[0,0,-1,1],DY=[-1,1,0,0];
881	function faceTile(){const fx=W.px+DX[W.face],fy=W.py+DY[W.face];if(fx<0||fy<0||fx>=SIZE||fy>=SIZE)return null;return{x:fx,y:fy,i:fy*SIZE+fx};}
