883	function nearestAnimal(){
884	  const f=faceTile();if(!f)return null;
885	  for(const a of W.animals){
886	    if(Math.abs(a.x-f.x)<1.5&&Math.abs(a.y-f.y)<1.5)return a;
887	  }
888	  // 也檢查玩家直接站旁邊的動物
889	  for(const a of W.animals){
890	    if(Math.abs(a.x-W.px)<1.5&&Math.abs(a.y-W.py)<1.5&&a!==null)return a;
891	  }
892	  return null;
893	}
