895	function animalAction(a){
896	  const info=ANIMAL_INFO[a.kind];
897	  if(a.state==='tamed'){
898	    if(a.resourceTimer<=0){
899	      return{label:'收集'+info.name+'的'+({fiber:'纖維',food:'雞蛋'}[info.resKind]||info.resKind),
900	        run(){gain(info.resKind,1);a.resourceTimer=a.resourceMax;toast(info.ico+'謝謝你的照顧!');sfx('pick');}
901	        ,stam:0};
902	    }
903	    const remain=Math.ceil(a.resourceTimer);
904	    return{label:'和'+info.name+'打招呼',run(){toast(info.ico+' '+info.petMsg+'(還要 '+remain+'秒)');},stam:0,soft:1};
905	  }
906	  if(W.inv.food<info.tameCost)
907	    return{label:'馴化'+info.name+'(需要糧食×'+info.tameCost+')',
908	      run(){toast('需要糧食×'+info.tameCost+' 才能馴化'+info.name);sfx('no');},stam:0,soft:1};
909	  return{label:'馴化'+info.name+'(糧食×'+info.tameCost+')',
910	    run(){W.inv.food-=info.tameCost;a.state='tamed';a.resourceTimer=a.resourceMax;
911	          W.stats.tamed=(W.stats.tamed||0)+1;
912	          toast(info.ico+' '+info.name+' 成為你的夥伴!');sfx('tame');renderInv();checkQuest();}
913	    ,stam:0};
914	}
