928	      run(){const n=Math.round((2+Math.floor(Math.random()*3))*chk.mul);gain('wood',n,f);
929	            if(Math.random()<.55)gain('sap',1);W.obj[f.i]=O.NONE;sfx('chop');},stam:6};
930	  }
931	  if(o===O.ROCK){
932	    const chk=checkHarvest('stone');
933	    if(!chk.ok)return{label:'採石(需要石稿)',run(){toast(chk.msg);sfx('no');},stam:0,soft:1};
934	    return{label:'開採岩石',run(){gain('stone',2+Math.floor(Math.random()*2),f);W.obj[f.i]=O.NONE;sfx('chop');},stam:7};
935	  }
936	  if(o===O.BERRY){
937	    if(W.aux[f.i]<0)return{label:'採摘漿果',run(){gain('food',2,f);if(Math.random()<.4)gain('seed',1);W.aux[f.i]=W.timeAcc+75;sfx('pick');},stam:3};
938	    return{label:'漿果還沒熟',run(){toast('再等等~');},stam:0,soft:1};
939	  }
940	  if(o===O.REED)return{label:'收割蘆葦',run(){gain('fiber',1+Math.floor(Math.random()*2),f);W.obj[f.i]=O.NONE;sfx('pick');},stam:3};
941	  if(o===O.CLAY){
942	    const chk=checkHarvest('clay');
943	    const n=Math.round((1+Math.floor(Math.random()*2))*chk.mul);
944	    return{label:'挖取黏土'+(chk.mul>1?'(×'+chk.mul+')':''),run(){gain('clay',n,f);W.aux[f.i]-=1;if(W.aux[f.i]<=0)W.obj[f.i]=O.NONE;sfx('chop');},stam:5};
945	  }
946	  if(o===O.FLOWER)return{label:'摘野花',run(){if(Math.random()<.5)gain('seed',1,f);else toast('一朵香香的小花 🌼');W.obj[f.i]=O.NONE;sfx('pick');},stam:1};
947	  if(o===O.SAPLING)return{label:'回收樹苗',run(){gain('sap',1,f);W.obj[f.i]=O.NONE;sfx('pick');},stam:1};
948	  if(o===O.RUIN){
949	    const id=W.aux[f.i]|0;
950	    if(!W.ruinFound[id])return{label:'調查遺跡',run(){W.ruinFound[id]=true;W.stats.ruinsFound++;gain('seed',3);gain('relic',1);toast('📜 '+RUIN_LORE[id]);sfx('ruin');},stam:2};
951	    return{label:'安靜的遺跡',run(){toast('石縫間長出了新芽。');},stam:0,soft:1};
952	  }
953	  if(o===O.FIRE||o===O.HUT)return{label:'休息到清晨',run(){restTillMorning();},stam:0};
954	  if(o===O.WELL)return{label:'喝口井水',run(){W.stam=Math.min(100,W.stam+8);toast('清涼!體力+8');sfx('eat');},stam:0};
955	  if(o===O.MONU)return{label:'仰望紀念碑',run(){toast('霧已經散了。這是你的島。');},stam:0,soft:1};
956	  if(o===O.WORKBENCH)return{label:'使用工作臺',run(){closePanels();craftTab='workbench';renderCraftPanel();document.getElementById('craftPanel').classList.add('open');},stam:0};
957	  if(o===O.LOOM)return{label:'使用織布機',run(){closePanels();craftTab='loom';renderCraftPanel();document.getElementById('craftPanel').classList.add('open');},stam:0};
958	  if(o===O.CROP){
959	    const st=cropStage(f.i);
