961	    return{label:'作物生長中 ('+['剛冒芽','已抽穗','快成熟'][st]+')',run(){toast('再等等~');},stam:0,soft:1};
962	  }
963	  if(t===T.FARM)
964	    return W.inv.seed>0
965	      ?{label:'播種',run(){W.inv.seed--;W.obj[f.i]=O.CROP;W.aux[f.i]=0;W.stats.farmsSown++;sfx('build');toast('種下一粒希望 🫘');},stam:2}
966	      :{label:'播種(缺種子)',run(){toast('沒有種子。漿果/野花/遺跡都有機會找到');},stam:0,soft:1};
967	  if(t===T.WATER||t===T.DEEP)return{label:'水面波光粼粼',run(){toast('可以蓋木橋,或用石材填土造地');},stam:0,soft:1};
