971	function gain(k,n,f){
972	  W.inv[k]=(W.inv[k]||0)+n;
973	  if(k==='wood')W.stats.gWood+=n;
974	  if(k==='stone')W.stats.gStone+=n;
975	  const r=RES_HUD.find(r=>r.k===k);
976	  if(f&&r)spawnFloat(f.x,f.y,r.ico+'+'+n);
977	  renderInv();
978	}
