980	function doInteract(){
981	  const a=contextAction();
982	  if(!a){toast('這裡沒什麼能做的');return;}
983	  if(a.stam>0&&W.stam<a.stam){toast('太累了……吃點東西(F)或到火邊休息');sfx('no');return;}
984	  W.stam-=a.stam;a.run();mmDirty=true;renderInv();checkQuest();
985	}
