987	function eatFood(){
988	  if(W.inv.food<=0){toast('沒有糧食了。找找漿果叢或種田吧');sfx('no');return;}
989	  if(W.stam>=99){toast('現在不餓');return;}
990	  W.inv.food--;W.stam=Math.min(100,W.stam+30);sfx('eat');toast('🍓 體力+30');renderInv();
991	  document.getElementById('foodCount').textContent=W.inv.food;
992	}
