1009	function growWorld(dt){
1010	  for(let y=0;y<SIZE;y++)for(let x=0;x<SIZE;x++){
1011	    const i=y*SIZE+x,o=W.obj[i];
1012	    if(o===O.CROP){const sp=nearWell(x,y)?2:1;W.aux[i]+=dt/55*sp;}
1013	    else if(o===O.SAPLING){W.aux[i]+=dt/110;if(W.aux[i]>=1){W.obj[i]=O.TREE;W.aux[i]=0;}}
1014	    else if(o===O.BERRY&&W.aux[i]>=0&&W.timeAcc>W.aux[i])W.aux[i]=-1;
1015	  }
1016	}
