1115	  if(t===T.MTN){ctx.fillStyle='#8d9187';ctx.beginPath();ctx.moveTo(sx+4,sy+TS-4);ctx.lineTo(sx+TS/2,sy+6);ctx.lineTo(sx+TS-4,sy+TS-4);ctx.closePath();ctx.fill();ctx.fillStyle='#e8ebe6';ctx.beginPath();ctx.moveTo(sx+TS/2-5,sy+13);ctx.lineTo(sx+TS/2,sy+6);ctx.lineTo(sx+TS/2+5,sy+13);ctx.closePath();ctx.fill();}
1116	  if(t===T.BRIDGE){ctx.strokeStyle='rgba(80,50,20,.4)';ctx.lineWidth=1.5;for(let k=6;k<TS;k+=8){ctx.beginPath();ctx.moveTo(sx,sy+k);ctx.lineTo(sx+TS,sy+k);ctx.stroke();}}
1117	  if(t===T.PATH){ctx.fillStyle='rgba(120,105,70,.3)';ctx.fillRect(sx+5,sy+5,9,7);ctx.fillRect(sx+20,sy+18,11,8);ctx.fillRect(sx+8,sy+24,8,7);}
1118	  if(t===T.FARM){ctx.strokeStyle='rgba(70,45,25,.45)';ctx.lineWidth=2;for(let k=7;k<TS;k+=9){ctx.beginPath();ctx.moveTo(sx+3,sy+k);ctx.lineTo(sx+TS-3,sy+k);ctx.stroke();}}
