function dirFromKeys(){
  if(keys['arrowup']||keys['w'])return 0;if(keys['arrowdown']||keys['s'])return 1;
  if(keys['arrowleft']||keys['a'])return 2;if(keys['arrowright']||keys['d'])return 3;return -1;
