/* ══════════ UI:背包 / 裝備 ══════════ */
function renderBagPanel(){
  // 裝備槽
  const slotsEl=document.getElementById('equipSlots');slotsEl.innerHTML='';
  const slotDef=[['head','頭部'],['body','身體'],['hand','工具']];
  for(const [slot,label] of slotDef){
    const equipped=W.equipped[slot];
    const info=equipped?EQUIP_DEF[equipped]:null;
    const d=document.createElement('div');d.className='eslot';
    d.innerHTML=`<span class="eslot-lbl">${label}</span><span class="eslot-item${info?'':' eslot-empty'}">${info?(info.ico+' '+info.name):'（空）'}</span>${info?`<button class="uneq" onclick="unequipSlot('${slot}')">卸下</button>`:''}`;
    slotsEl.appendChild(d);
  }
  if(W.equipped.hand||W.equipped.head||W.equipped.body){
    const desc=document.createElement('div');
    desc.style.cssText='font-size:11px;color:#6b5d3f;padding:4px 2px;line-height:1.6;';
    const lines=[];
    for(const slot of ['head','body','hand']){
      const eq=W.equipped[slot];
      if(eq&&EQUIP_DEF[eq])lines.push(EQUIP_DEF[eq].ico+' '+EQUIP_DEF[eq].desc);
    }
    desc.textContent='效果:'+lines.join(' · ');
    slotsEl.appendChild(desc);
  }
  // 未裝備的裝備品
  const invEqEl=document.getElementById('invEquipList');invEqEl.innerHTML='';
  const available=Object.keys(EQUIP_DEF).filter(k=>(W.inv[k]||0)>0);
  if(available.length){
    const title=document.createElement('b');title.textContent='可裝備的物品';invEqEl.appendChild(title);
    for(const k of available){
      const def=EQUIP_DEF[k];
      const d=document.createElement('div');d.className='eitem';
      d.innerHTML=`<span class="eitem-ico">${def.ico}</span><div style="flex:1"><span class="eitem-lbl">${def.name}</span><div class="eitem-desc">${def.desc}</div></div><span style="font-size:11px;color:#8a7a52;margin-right:6px">×${W.inv[k]}</span><button class="eq-btn" onclick="equipItem('${k}')">裝備</button>`;
      invEqEl.appendChild(d);
    }

