394	    if(e<0.18)ter[i]=T.DEEP;else if(e<0.30)ter[i]=T.WATER;
395	    else if(e<0.355)ter[i]=T.SAND;else if(e>0.78)ter[i]=T.MTN;
396	    else if(e>0.66)ter[i]=T.ROCKY;else if(m>0.58&&e>0.42)ter[i]=T.FOREST;
397	    else if(m>0.46)ter[i]=T.MEADOW;else ter[i]=T.GRASS;
