402	      if(ter[i-1]<=T.WATER||ter[i+1]<=T.WATER||ter[i-SIZE]<=T.WATER||ter[i+SIZE]<=T.WATER)
403	        if(rng()<.6)ter[i]=T.SAND;
404	    }
405	  }
