414	      if(nearW&&r<.18)obj[i]=O.REED;else if(nearW&&r<.27){obj[i]=O.CLAY;aux[i]=3;}
415	    }
416	    if(obj[i]===O.BERRY)aux[i]=-1;
417	  }
418	  let spawn=null,best=1e9;
419	  for(let y=8;y<SIZE-8;y++)for(let x=8;x<SIZE-8;x++){
420	    const i=y*SIZE+x;
421	    if((ter[i]===T.GRASS||ter[i]===T.MEADOW)&&obj[i]===O.NONE){
422	      const d=(x-SIZE/2)**2+(y-SIZE/2)**2;if(d<best){best=d;spawn={x,y};}
423	    }
424	  }
