439	      const i=c.y*SIZE+c.x;obj[i]=O.RUIN;aux[i]=ruins.length-1;
440	      for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){
441	        const j=(c.y+dy)*SIZE+(c.x+dx);
442	        if(j!==i&&obj[j]!==O.RUIN&&ter[j]>=T.SAND&&ter[j]!==T.MTN)obj[j]=O.NONE;
443	      }
444	    }
445	  }
446	  // 動物生成
447	  const animals=[];let aid=0;
448	  const animalSpecs=[
449	    {kind:AK.RABBIT,  allowed:[T.MEADOW,T.GRASS],  count:4},
450	    {kind:AK.CHICKEN, allowed:[T.GRASS,T.MEADOW],  count:3},
