379	function makeNoise(rng,g){const a=new Float32Array(g*g);for(let i=0;i<a.length;i++)a[i]=rng();return function(x,y){const gx=x*(g-1),gy=y*(g-1),x0=Math.floor(gx),y0=Math.floor(gy),fx=gx-x0,fy=gy-y0,sx=fx*fx*(3-2*fx),sy=fy*fy*(3-2*fy),i=(xx,yy)=>a[clamp(yy,0,g-1)*g+clamp(xx,0,g-1)],av=i(x0,y0)+(i(x0+1,y0)-i(x0,y0))*sx,bv=i(x0,y0+1)+(i(x0+1,y0+1)-i(x0,y0+1))*sx;return av+(bv-av)*sy;};}
380	function fbm(ns,x,y){let v=0,amp=.55,f=1,tot=0;for(let i=0;i<ns.length;i++){v+=ns[i](((x*f)%1+1)%1,((y*f)%1+1)%1)*amp;tot+=amp;amp*=.5;f*=2.03;}return v/tot;}
