816	function updateAnimals(dt){
817	  for(const a of W.animals){
818	    // 資源計時
819	    if(a.state==='tamed'&&a.resourceTimer>0)a.resourceTimer-=dt;
820	    // 逃跑計時
821	    if(a.fleeTimer>0){a.fleeTimer-=dt;if(a.fleeTimer<=0&&a.state==='fleeing'){a.state='wild';a.vx=0;a.vy=0;}}
822	    // 行為
823	    if(a.state==='wild'){
824	      const dist=Math.hypot(a.x-W.px,a.y-W.py);
825	      if(dist<2.5){
826	        const ang=Math.atan2(a.y-W.py,a.x-W.px);
827	        a.vx=Math.cos(ang)*2.8;a.vy=Math.sin(ang)*2.8;
828	        a.state='fleeing';a.fleeTimer=2.5;
829	      }else if(a.state!=='fleeing'&&Math.random()<dt*0.4){
830	        const ang=Math.random()*Math.PI*2;
831	        a.vx=Math.cos(ang)*0.5;a.vy=Math.sin(ang)*0.5;
832	      }
833	    }else if(a.state==='tamed'){
834	      const dist=Math.hypot(a.x-W.px,a.y-W.py);
835	      if(dist>5){
836	        const ang=Math.atan2(W.py-a.y,W.px-a.x);
837	        a.vx=Math.cos(ang)*0.8;a.vy=Math.sin(ang)*0.8;
838	      }else if(dist<0.5){
839	        const ang=Math.atan2(a.y-W.py,a.x-W.px)||0;
840	        a.vx=Math.cos(ang)*0.3;a.vy=Math.sin(ang)*0.3;
841	      }else if(Math.random()<dt*0.3){
842	        const ang=Math.random()*Math.PI*2;a.vx=Math.cos(ang)*0.2;a.vy=Math.sin(ang)*0.2;
843	      }
844	      // 動物間互斥：太近就互相推開
845	      for(const b of W.animals){
846	        if(b===a)continue;
847	        const sep=Math.hypot(a.x-b.x,a.y-b.y);
848	        if(sep<1.2&&sep>0){
849	          const ang=Math.atan2(a.y-b.y,a.x-b.x);
850	          a.vx+=Math.cos(ang)*0.4;a.vy+=Math.sin(ang)*0.4;
851	        }
852	      }
853	    }
854	    // 移動
855	    const nx=a.x+a.vx*dt,ny=a.y+a.vy*dt;
856	    if(!isBlockedForAnimal(Math.floor(nx),Math.floor(ny)))
857	      {a.x=clamp(nx,0.5,SIZE-0.5);a.y=clamp(ny,0.5,SIZE-0.5);}
858	    else{a.vx=0;a.vy=0;}
859	    // 速度阻尼
860	    a.vx*=0.92;a.vy*=0.92;
861	  }
862	}
