function nearestAnimal(){
  const f=faceTile();if(!f)return null;
  // 寵物用更嚴格的距離（1.0），避免擋住地圖互動；野生動物沿用 1.5
  for(const a of W.animals){
    const th=a.state==='tamed'?1.0:1.5;
    if(Math.abs(a.x-f.x)<th&&Math.abs(a.y-f.y)<th)return a;
  }
  // 玩家周圍只偵測野生動物，寵物不在此攔截
  for(const a of W.animals){
    if(a.state!=='tamed'&&Math.abs(a.x-W.px)<1.5&&Math.abs(a.y-W.py)<1.5)return a;
  }
  return null;
}

function animalAction(a){
  const info=ANIMAL_INFO[a.kind];
  if(a.state==='tamed'){
    if(a.resourceTimer<=0){
      return{label:'收集'+info.name+'的'+({fiber:'纖維',food:'雞蛋'}[info.resKind]||info.resKind),
        run(){gain(info.resKind,1);a.resourceTimer=a.resourceMax;toast(info.ico+'謝謝你的照顧!');sfx('pick');}
        ,stam:0};
    }
    const remain=Math.ceil(a.resourceTimer);
    return{label:'和'+info.name+'打招呼',run(){toast(info.ico+' '+info.petMsg+'(還要 '+remain+'秒)');},stam:0,soft:1};
  }
  if(W.inv.food<info.tameCost)
    return{label:'馴化'+info.name+'(需要糧食×'+info.tameCost+')',
      run(){toast('需要糧食×'+info.tameCost+' 才能馴化'+info.name);sfx('no');},stam:0,soft:1};
  return{label:'馴化'+info.name+'(糧食×'+info.tameCost+')',
    run(){W.inv.food-=info.tameCost;a.state='tamed';a.fleeTimer=0;a.resourceTimer=a.resourceMax;
          W.stats.tamed=(W.stats.tamed||0)+1;
          toast(info.ico+' '+info.name+' 成為你的夥伴!');sfx('tame');renderInv();checkQuest();}
    ,stam:0};
}

function cropStage(i){return Math.min(2,Math.floor(W.aux[i]));}
function nearWell(x,y){for(let dy=-3;dy<=3;dy++)for(let dx=-3;dx<=3;dx++){const nx=x+dx,ny=y+dy;if(nx<0||ny<0||nx>=SIZE||ny>=SIZE)continue;if(W.obj[ny*SIZE+nx]===O.WELL)return true;}return false;}

function contextAction(){
  // 先看動物
  const animal=nearestAnimal();
  if(animal)return animalAction(animal);
  const f=faceTile();if(!f)return null;
  const o=W.obj[f.i],t=W.ter[f.i];
  if(o===O.TREE){
    const chk=checkHarvest('wood');
    return{label:'砍伐樹木'+(chk.mul>1?'(×'+chk.mul+'效率)':''),
      run(){const n=Math.round((2+Math.floor(Math.random()*3))*chk.mul);gain('wood',n,f);
            if(Math.random()<.55)gain('sap',1);W.obj[f.i]=O.NONE;wearEquip('hand');sfx('chop');},stam:6};
  }
  if(o===O.ROCK){
    const chk=checkHarvest('stone');
    const rockLabel=chk.bare?'徒手鑿石(效率低,先湊 3 顆做石稿)':'開採岩石';
    return{label:rockLabel,run(){const n=Math.max(1,Math.round((2+Math.floor(Math.random()*2))*chk.mul));gain('stone',n,f);W.obj[f.i]=O.NONE;if(!chk.bare)wearEquip('hand');sfx('chop');},stam:chk.bare?12:7};
  }
  if(o===O.BERRY){
    if(W.aux[f.i]<0)return{label:'採摘漿果',run(){gain('food',2,f);if(Math.random()<.4)gain('seed',1);W.aux[f.i]=W.timeAcc+75;sfx('pick');},stam:3};
    return{label:'漿果還沒熟',run(){toast('再等等~');},stam:0,soft:1};
  }
  if(o===O.REED)return{label:'收割蘆葦',run(){gain('fiber',1+Math.floor(Math.random()*2),f);W.obj[f.i]=O.NONE;sfx('pick');},stam:3};
  if(o===O.CLAY){
    const chk=checkHarvest('clay');
    const n=Math.round((1+Math.floor(Math.random()*2))*chk.mul);
    return{label:'挖取黏土'+(chk.mul>1?'(×'+chk.mul+')':''),run(){gain('clay',n,f);W.aux[f.i]-=1;if(W.aux[f.i]<=0)W.obj[f.i]=O.NONE;sfx('chop');},stam:5};
  }
  if(o===O.FLOWER)return{label:'摘野花',run(){if(Math.random()<.5)gain('seed',1,f);else toast('一朵香香的小花 🌼');W.obj[f.i]=O.NONE;sfx('pick');},stam:1};
  if(o===O.SAPLING)return{label:'回收樹苗',run(){gain('sap',1,f);W.obj[f.i]=O.NONE;sfx('pick');},stam:1};
  if(o===O.RUIN){
    const id=W.aux[f.i]|0;
    if(!W.ruinFound[id])return{label:'調查遺跡',run(){W.ruinFound[id]=true;W.stats.ruinsFound++;gain('seed',3);gain('relic',1);toast('📜 '+RUIN_LORE[id]);sfx('ruin');},stam:2};
    return{label:'安靜的遺跡',run(){toast('石縫間長出了新芽。');},stam:0,soft:1};
  }
  if(o===O.FIRE||o===O.HUT)return{label:'休息到清晨',run(){restTillMorning();},stam:0};
  if(o===O.WELL)return{label:'喝口井水',run(){W.stam=Math.min(100,W.stam+8);toast('清涼!體力+8');sfx('eat');},stam:0};
  if(o===O.MONU)return{label:'仰望紀念碑',run(){toast('霧已經散了。這是你的島。');},stam:0,soft:1};
  for(const [stId,station] of Object.entries(STATIONS)){
    if(station.objType&&o===station.objType)
      return{label:'使用'+station.name,run(){closePanels();craftTab=stId;renderCraftPanel();document.getElementById('craftPanel').classList.add('open');},stam:0};
  }
  if(o===O.CROP){
    const st=cropStage(f.i);
    if(st>=2)return{label:'收割作物',run(){gain('food',3,f);if(Math.random()<.8)gain('seed',1);W.obj[f.i]=O.NONE;W.stats.cropsHarvested++;sfx('pick');},stam:3};
    return{label:'作物生長中 ('+['剛冒芽','已抽穗','快成熟'][st]+')',run(){toast('再等等~');},stam:0,soft:1};
  }
  if(t===T.FARM)
    return W.inv.seed>0
      ?{label:'播種',run(){W.inv.seed--;W.obj[f.i]=O.CROP;W.aux[f.i]=0;W.stats.farmsSown++;sfx('build');toast('種下一粒希望 🫘');},stam:2}
      :{label:'播種(缺種子)',run(){toast('沒有種子。漿果/野花/遺跡都有機會找到');},stam:0,soft:1};
  if(t===T.WATER||t===T.DEEP)return{label:'水面波光粼粼',run(){toast('可以蓋木橋,或用石材填土造地');},stam:0,soft:1};
  return null;
}

function gain(k,n,f){
  W.inv[k]=(W.inv[k]||0)+n;
  if(k==='wood')W.stats.gWood+=n;
  if(k==='stone')W.stats.gStone+=n;
  const r=RESOURCES[k];
  if(f&&r)spawnFloat(f.x,f.y,r.ico+'+'+n);
  renderInv();
}

function doInteract(){
  const a=contextAction();
  if(!a){toast('這裡沒什麼能做的');return;}
  if(a.stam>0&&W.stam<a.stam){toast('太累了……吃點東西(E)或到火邊休息');sfx('no');return;}
  W.stam-=a.stam;a.run();mmDirty=true;renderInv();checkQuest();
}

function eatFood(){
  if(W.inv.food<=0){toast('沒有糧食了。找找漿果叢或種田吧');sfx('no');return;}
  if(W.stam>=99){toast('現在不餓');return;}
  W.inv.food--;W.stam=Math.min(100,W.stam+30);sfx('eat');toast('🍓 體力+30');renderInv();
  document.getElementById('foodCount').textContent=W.inv.food;
}

function restTillMorning(){
  const fade=document.getElementById('fade');
  fade.style.opacity=1;
  setTimeout(()=>{W.day++;W.tod=0.24;W.stam=100;growWorld(DAY_LEN*0.4);updateHUD();save();toast('☀️ 新的一天,第'+W.day+'天');fade.style.opacity=0;},650);
}
function onMonument(){
  setTimeout(()=>{
    let discN=0;for(let i=0;i<W.disc.length;i++)if(W.disc[i])discN++;
    document.getElementById('endStats').innerHTML='⏳ 開拓天數:'+W.day+'天<br>🗺️ 探索比例:'+Math.round(discN/(SIZE*SIZE)*100)+'%<br>🛠️ 建造次數:'+W.stats.builds+'次<br>🐾 馴化動物:'+(W.stats.tamed||0)+'隻';
    document.getElementById('ending').classList.add('open');W.freePlay=true;sfx('quest');
  },500);
}
document.getElementById('btnFree').onclick=()=>document.getElementById('ending').classList.remove('open');

/* ══════════ 世界生長 ══════════ */
function growWorld(dt){
  for(let y=0;y<SIZE;y++)for(let x=0;x<SIZE;x++){
    const i=y*SIZE+x,o=W.obj[i];
    if(o===O.CROP){const sp=nearWell(x,y)?2:1;W.aux[i]+=dt/55*sp;}
    else if(o===O.SAPLING){W.aux[i]+=dt/110;if(W.aux[i]>=1){W.obj[i]=O.TREE;W.aux[i]=0;}}
    else if(o===O.BERRY&&W.aux[i]>=0&&W.timeAcc>W.aux[i])W.aux[i]=-1;
  }
}

