    for(let k=-8;k<=8;k+=8){ctx.beginPath();ctx.moveTo(cx+k,sy+TS-5);ctx.lineTo(cx+k,sy+TS-5-hgt);ctx.stroke();
      if(st===2){ctx.fillStyle='#e8c050';circle(cx+k,sy+TS-7-hgt,3.5);}
