const SAVE_KEY='isle-pioneer-v2';
function save(){
  if(!W)return;
  try{
    const d={seedStr:W.seedStr,ter:Array.from(W.ter),obj:Array.from(W.obj),
      aux:Array.from(W.aux),disc:Array.from(W.disc),
      px:W.px,py:W.py,face:W.face,stam:W.stam,day:W.day,tod:W.tod,timeAcc:W.timeAcc,
      inv:W.inv,equipped:W.equipped,equipDur:W.equipDur,animals:W.animals,
      stats:W.stats,questIdx:W.questIdx,freePlay:W.freePlay,ruinFound:W.ruinFound};
    localStorage.setItem(SAVE_KEY,JSON.stringify(d));
  }catch(e){}
}
function load(){
  try{
    const raw=localStorage.getItem(SAVE_KEY);if(!raw)return null;
    const d=JSON.parse(raw);
    const w=genWorld(d.seedStr);
    w.ter=Uint8Array.from(d.ter);w.obj=Uint8Array.from(d.obj);
    w.aux=Float32Array.from(d.aux);w.disc=Uint8Array.from(d.disc);
    // 安全合併 inv (相容舊存檔缺少新 key)
    Object.assign(w.inv,d.inv);
    Object.assign(w,{px:d.px,py:d.py,face:d.face,stam:d.stam,day:d.day,tod:d.tod,
      timeAcc:d.timeAcc||0,equipped:d.equipped||{head:null,body:null,hand:null},
      equipDur:d.equipDur||{head:null,body:null,hand:null},
      animals:d.animals||[],stats:d.stats||{},questIdx:d.questIdx,
      freePlay:d.freePlay,ruinFound:d.ruinFound});
    // 補齊 stats 欄位
    w.stats=Object.assign({gWood:0,gStone:0,fires:0,huts:0,farmsSown:0,cropsHarvested:0,bridges:0,ruinsFound:0,monu:0,builds:0,workbenches:0,tamed:0},w.stats);
    return w;
  }catch(e){return null;}
}
setInterval(()=>{if(running)save();},15000);
document.addEventListener('visibilitychange',()=>{if(document.hidden)save();});

/* ══════════ 主迴圈 ══════════ */
let last=0,growAcc=0,ambTick=0;
function loop(ts){
  requestAnimationFrame(loop);if(!running)return;
  const dt=Math.min(0.05,(ts-last)/1000||0.016);last=ts;
  W.timeAcc=(W.timeAcc||0)+dt;
  // 時間推進
  const prevTod=W.tod;W.tod+=dt/DAY_LEN;if(W.tod>=1){W.tod-=1;}
  if(prevTod<0.24&&W.tod>=0.24){W.day++;toast('☀️ 第 '+W.day+' 天');}
  // 移動（含 deadlock：新方向先轉身鎖定 300ms，短暫觸發只轉向不位移）
  moveCd-=dt;
  const d=heldDir>=0?heldDir:dirFromKeys();
  if(d>=0){
    if(d!==prevDir){W.face=d;turnLock=0.30;}
    prevDir=d;
    turnLock=Math.max(0,turnLock-dt);
    if(turnLock<=0){tryMove(d);walkPhase+=dt*12;}
  }else{prevDir=-1;turnLock=0;walkPhase=0;}
  // 體力
  const body=W.equipped.body,nightNow=isNight(),hat=W.equipped.head==='hat';
  if(d<0){
    if(nightNow){
      if(body==='wool_coat')W.stam=Math.min(100,W.stam+dt*.7);
      else if(body==='coat')W.stam=Math.min(100,W.stam+dt*.3);
      else if(body==='shirt')W.stam=Math.max(0,W.stam-dt*.4);
      else W.stam=Math.max(0,W.stam-dt*.9);
    }else{
      const rate=1.2*(hat?1.2:1);W.stam=Math.min(100,W.stam+dt*rate);
    }
  }
  // 動物
  updateAnimals(dt);
  // 世界生長
  growAcc+=dt;if(growAcc>=1){growWorld(growAcc);growAcc=0;}
  // 環境音樂排程
  ambTick-=dt;if(ambTick<=0){ambTick=2;scheduleAmbient();}
  render();mmPlayer();updateHUD();
}
requestAnimationFrame(loop);

