1	<!DOCTYPE html>
2	<html lang="zh-Hant">
3	<head>
4	<meta charset="UTF-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no, viewport-fit=cover">
6	<title>小島開拓誌</title>
7	<style>
8	:root{--ink:#2b3a30;--paper:#f4ecd9;--paper2:#e9dec4;--moss:#7da462;--terra:#c4744a;--lake:#5d9bb5;--gold:#d8a94e;--line:#c9b990;}
9	*{margin:0;padding:0;box-sizing:border-box;-webkit-tap-highlight-color:transparent;}
10	html,body{width:100%;height:100%;overflow:hidden;background:#11201a;}
11	body{font-family:"PingFang TC","Microsoft JhengHei","Noto Sans TC",system-ui,sans-serif;color:var(--ink);user-select:none;-webkit-user-select:none;}
12	canvas#game{position:fixed;inset:0;width:100%;height:100%;display:block;touch-action:none;}
13	.hud{position:fixed;z-index:5;pointer-events:none;}
14	#topbar{top:10px;left:10px;display:flex;gap:7px;align-items:flex-start;flex-wrap:wrap;max-width:calc(100% - 158px);}
15	.card{background:var(--paper);border:2px solid var(--ink);border-radius:10px;box-shadow:3px 3px 0 rgba(0,0,0,.35);padding:5px 9px;pointer-events:auto;}
16	#daycard{display:flex;align-items:center;gap:8px;font-weight:700;font-size:13px;}
17	#stamWrap{display:flex;align-items:center;gap:5px;}
18	#stamBar{width:88px;height:9px;background:var(--paper2);border:1.5px solid var(--ink);border-radius:6px;overflow:hidden;}
19	#stamFill{height:100%;width:100%;background:linear-gradient(90deg,#9fc57e,#7da462);transition:width .25s;}
20	#invbar{display:flex;gap:4px;flex-wrap:wrap;}
21	.slot{display:flex;align-items:center;gap:3px;font-size:12px;font-weight:700;background:var(--paper2);border:1.5px solid var(--line);border-radius:7px;padding:2px 6px;min-width:40px;justify-content:center;}
22	.slot .ico{font-size:14px;}
23	#minimapCard{position:fixed;top:10px;right:10px;z-index:5;padding:4px;}
24	#minimap{display:block;width:130px;height:130px;image-rendering:pixelated;border:1.5px solid var(--line);border-radius:6px;background:#1c2c24;}
25	#mmLabel{text-align:center;font-size:10px;font-weight:700;margin-top:2px;letter-spacing:2px;color:#6b5d3f;}
26	#hint{position:fixed;left:50%;transform:translateX(-50%);bottom:120px;z-index:5;background:rgba(43,58,48,.9);color:var(--paper);padding:5px 13px;border-radius:999px;font-size:12.5px;font-weight:700;letter-spacing:.5px;pointer-events:none;opacity:0;transition:opacity .2s;white-space:nowrap;max-width:80vw;}
27	#hint.show{opacity:1;}
28	#toasts{position:fixed;left:50%;transform:translateX(-50%);top:60px;z-index:8;display:flex;flex-direction:column;gap:5px;align-items:center;pointer-events:none;}
29	.toast{background:var(--paper);border:2px solid var(--ink);border-radius:10px;padding:5px 13px;font-size:12.5px;font-weight:700;box-shadow:3px 3px 0 rgba(0,0,0,.35);animation:toastIn .25s ease,toastOut .4s ease 2.6s forwards;max-width:86vw;text-align:center;}
30	.toast.quest{background:#fdf3d7;border-color:#9a7d2e;color:#6e5717;}
31	@keyframes toastIn{from{opacity:0;transform:translateY(-8px);}to{opacity:1;transform:none;}}
32	@keyframes toastOut{to{opacity:0;transform:translateY(-8px);}}
33	/* ─── bottom controls ─── */
34	#controls{position:fixed;inset-inline:0;bottom:0;z-index:6;display:flex;justify-content:space-between;align-items:flex-end;padding:0 12px calc(12px + env(safe-area-inset-bottom));pointer-events:none;}
35	#dpad{position:relative;width:126px;height:126px;pointer-events:auto;}
36	.dbtn{position:absolute;width:42px;height:42px;background:var(--paper);border:2px solid var(--ink);border-radius:9px;display:flex;align-items:center;justify-content:center;font-size:16px;font-weight:900;color:var(--ink);box-shadow:2px 2px 0 rgba(0,0,0,.35);}
37	.dbtn:active,.dbtn.on{background:var(--moss);color:#fff;transform:translate(1px,1px);box-shadow:none;}
38	#d-up{top:0;left:42px;}#d-down{bottom:0;left:42px;}#d-left{top:42px;left:0;}#d-right{top:42px;right:0;}
39	#abtns{display:flex;gap:6px;align-items:flex-end;pointer-events:auto;}
40	.abtn{width:44px;height:44px;border-radius:50%;background:var(--paper);border:2.5px solid var(--ink);box-shadow:3px 3px 0 rgba(0,0,0,.35);display:flex;flex-direction:column;align-items:center;justify-content:center;font-weight:900;font-size:11px;color:var(--ink);cursor:pointer;gap:1px;line-height:1;}
41	.abtn small{font-size:8px;font-weight:700;opacity:.5;}
42	.abtn:active{transform:translate(2px,2px);box-shadow:none;}
43	#btnAct{width:56px;height:56px;background:#f3d98b;border-color:#7a611f;color:#5c4a16;font-size:12px;}
44	@media (hover:hover) and (pointer:fine){#dpad{display:none;}}
45	/* ─── panels ─── */
46	.panel{position:fixed;z-index:10;left:50%;top:50%;transform:translate(-50%,-50%);background:var(--paper);border:3px solid var(--ink);border-radius:14px;box-shadow:6px 6px 0 rgba(0,0,0,.4);width:min(500px,95vw);max-height:min(82vh,590px);display:none;flex-direction:column;overflow:hidden;}
47	.panel.open{display:flex;}
48	.phead{display:flex;justify-content:space-between;align-items:center;padding:9px 13px;border-bottom:2px dashed var(--line);background:var(--paper2);flex:none;}
49	.phead h2{font-size:14.5px;letter-spacing:2px;}
50	.pclose{border:2px solid var(--ink);background:var(--paper);border-radius:8px;width:27px;height:27px;font-weight:900;cursor:pointer;font-size:13px;color:var(--ink);}
51	.pbody{padding:10px 12px;overflow-y:auto;flex:1;}
52	/* craft tabs */
53	.tabs{display:flex;gap:5px;padding:7px 12px;border-bottom:1px solid var(--line);background:var(--paper2);flex:none;flex-wrap:wrap;}
54	.tab{padding:4px 10px;border:1.5px solid var(--line);border-radius:8px;font-size:11.5px;font-weight:800;cursor:pointer;color:#8a7a52;background:transparent;}
55	.tab.active{background:var(--moss);color:#fff;border-color:#56753f;}
56	.tab.locked{opacity:.4;cursor:default;}
57	/* recipe rows */
58	.ritem{display:flex;align-items:center;gap:9px;padding:7px 8px;border:1.5px solid var(--line);border-radius:9px;margin-bottom:5px;background:#fbf5e6;}
59	.ritem.cant{opacity:.45;}
60	.rico{font-size:21px;width:28px;text-align:center;}
61	.rinfo{flex:1;min-width:0;}
62	.rinfo b{font-size:13px;display:block;}
63	.rinfo span{font-size:11px;color:#6b5d3f;display:block;margin-top:1px;}
64	.rcost{font-size:11px;font-weight:800;color:#7a611f;white-space:nowrap;margin-right:4px;}
65	.rmake{border:2px solid #56753f;border-radius:8px;padding:4px 9px;font-size:11.5px;font-weight:800;cursor:pointer;background:var(--moss);color:#fff;flex:none;font-family:inherit;}
66	.rmake:active{transform:scale(.94);}
67	.rmake:disabled{background:var(--paper2);color:#aaa;border-color:#ccc;cursor:not-allowed;}
68	/* bag / equip panel */
69	.bagFlex{display:flex;gap:12px;flex-wrap:wrap;}
70	#dollWrap{flex:none;}
71	#dollCanvas{display:block;border:2px solid var(--line);border-radius:10px;width:80px;height:120px;background:var(--paper2);}
72	.equipSlots{flex:1;min-width:155px;}
73	.eslot{display:flex;align-items:center;gap:7px;padding:5px 8px;border:1.5px solid var(--line);border-radius:8px;margin-bottom:5px;background:#fbf5e6;}
74	.eslot-lbl{font-size:10.5px;font-weight:800;color:#8a7a52;width:26px;flex:none;}
75	.eslot-item{flex:1;font-size:12.5px;font-weight:700;}
76	.eslot-empty{color:#bfb8a0;font-style:italic;font-size:12px;}
77	.uneq{font-size:10.5px;font-weight:800;cursor:pointer;border:1.5px solid #c47a4a;border-radius:6px;padding:2px 6px;color:#a05030;background:transparent;}
78	.invEq{margin-top:8px;}
79	.invEq>b{font-size:10.5px;font-weight:800;letter-spacing:2px;color:#8a7a52;display:block;margin-bottom:4px;}
80	.eitem{display:flex;align-items:center;gap:7px;padding:5px 7px;border:1.5px solid var(--line);border-radius:8px;margin-bottom:4px;background:#fbf5e6;}
81	.eitem-ico{font-size:18px;width:24px;text-align:center;}
82	.eitem-lbl{flex:1;font-size:12.5px;font-weight:700;}
83	.eitem-desc{font-size:10px;color:#6b5d3f;}
84	.eq-btn{font-size:10.5px;font-weight:800;cursor:pointer;border:1.5px solid var(--moss);border-radius:6px;padding:2px 6px;color:#3a6030;background:transparent;font-family:inherit;}
85	.foodrow{margin-top:7px;display:flex;align-items:center;gap:8px;padding:6px 8px;border:2px dashed var(--line);border-radius:8px;}
86	.foodrow span{font-size:12.5px;font-weight:700;flex:1;}
87	.eatbtn{padding:5px 11px;border:2px solid var(--ink);border-radius:8px;font-size:12.5px;font-weight:800;cursor:pointer;background:var(--terra);color:#fff;font-family:inherit;}
88	/* quest / build */
89	.qitem{display:flex;gap:8px;padding:7px 3px;border-bottom:1.5px dashed var(--line);font-size:13px;align-items:flex-start;}
90	.qitem .chk{width:18px;height:18px;border:2px solid var(--ink);border-radius:6px;flex:none;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:900;background:#fff;margin-top:1px;}
91	.qitem.done{opacity:.5;}.qitem.done .chk{background:var(--moss);color:#fff;border-color:#56753f;}
92	.qitem.cur b{color:var(--terra);}
93	.qitem span{display:block;font-size:11px;color:#6b5d3f;margin-top:1px;}
94	.bitem{display:flex;align-items:center;gap:9px;padding:7px;border:2px solid var(--line);border-radius:9px;margin-bottom:7px;background:#fbf5e6;cursor:pointer;}
95	.bitem:active{background:#efe6cd;}.bitem.locked{opacity:.4;cursor:not-allowed;}
96	.bico{font-size:22px;width:30px;text-align:center;}
97	.binfo{flex:1;min-width:0;}
98	.binfo b{font-size:13.5px;}
99	.binfo span{font-size:11px;color:#6b5d3f;display:block;margin-top:1px;}
100	.bcost{font-size:11.5px;font-weight:800;color:#7a611f;white-space:nowrap;}

100	.bcost{font-size:11.5px;font-weight:800;color:#7a611f;white-space:nowrap;}
101	.bsec{font-size:10px;font-weight:800;letter-spacing:3px;color:#8a7a52;margin:9px 2px 5px;}
102	/* title */
103	#title{position:fixed;inset:0;z-index:20;background:radial-gradient(ellipse at 50% 30%,#27433a,#101f19 75%);display:flex;align-items:center;justify-content:center;flex-direction:column;gap:16px;padding:20px;}
104	#titleCard{background:var(--paper);border:3px solid var(--ink);border-radius:18px;box-shadow:8px 8px 0 rgba(0,0,0,.45);padding:26px 28px 22px;text-align:center;width:min(400px,92vw);}
