209	'use strict';
210	(function(){
211	
212	/* ══════════ 音效 ══════════ */
213	let AC=null, masterGain=null, droneNode=null, ambNextTime=0, muted=false;
214	
215	function initAudio(){
216	  if(AC)return;
217	  try{
218	    AC=new(window.AudioContext||window.webkitAudioContext)();
219	    masterGain=AC.createGain();
220	    masterGain.gain.value=1;
221	    masterGain.connect(AC.destination);
222	    startDrone();
223	    scheduleAmbient();
224	  }catch(e){}
225	}
226	['pointerdown','keydown'].forEach(ev=>document.addEventListener(ev,initAudio,{once:true}));
227	
228	function startDrone(){
229	  if(!AC||droneNode)return;
230	  droneNode=AC.createOscillator();
231	  const g=AC.createGain(),f=AC.createBiquadFilter();
232	  f.type='lowpass';f.frequency.value=340;
233	  g.gain.value=muted?0:0.032;
234	  droneNode.type='sine';droneNode.frequency.value=130.8;
235	  droneNode.connect(f);f.connect(g);g.connect(masterGain);
236	  droneNode.start();
237	  droneNode._g=g;
238	}
239	
240	function playNote(freq,time,dur,vol){
241	  if(!AC||muted)return;
242	  const o=AC.createOscillator(),g=AC.createGain();
243	  o.type='sine';o.frequency.value=freq;
244	  o.connect(g);g.connect(masterGain);
245	  g.gain.setValueAtTime(0,time);
246	  g.gain.linearRampToValueAtTime(vol||0.055,time+0.07);
247	  g.gain.exponentialRampToValueAtTime(0.0001,time+dur);
248	  o.start(time);o.stop(time+dur+0.05);

249	}
250	
251	function scheduleAmbient(){
252	  if(!AC||muted){ambNextTime=0;return;}
253	  const now=AC.currentTime;
254	  if(ambNextTime>now+3)return;
255	  const night=W&&isNight();
256	  const sc=night?[196,220,261.6,311.1,349.2,261.6]:[261.6,293.7,329.6,392,440,523.3];
257	  let t=Math.max(now+0.1,ambNextTime);
258	  for(let i=0;i<5;i++){
259	    const freq=sc[Math.floor(Math.random()*sc.length)]*(Math.random()<0.25?2:1);
260	    const dur=0.45+Math.random()*0.9;
261	    playNote(freq,t,dur,night?0.04:0.055);
262	    t+=0.7+Math.random()*2.8;
263	  }
264	  ambNextTime=t;
265	}
266	
267	function sfx(kind){
268	  if(!AC||muted)return;
269	  if(AC.state==='suspended')AC.resume();
270	  const t=AC.currentTime;
271	  const P={
272	    chop:[180,90,'square',.1],pick:[520,740,'sine',.07],
273	    build:[300,200,'triangle',.1],eat:[660,900,'sine',.07],
274	    quest:[523,784,'sine',.12],step:[160,130,'sine',.02],
275	    no:[220,150,'sawtooth',.07],ruin:[392,660,'triangle',.12],
276	    tame:[520,660,'triangle',.1]
277	  }[kind]||[440,440,'sine',.06];
278	  const o=AC.createOscillator(),g=AC.createGain();
279	  o.type=P[2];o.frequency.setValueAtTime(P[0],t);
280	  o.frequency.exponentialRampToValueAtTime(Math.max(P[1],1),t+.13);
281	  g.gain.setValueAtTime(P[3],t);g.gain.exponentialRampToValueAtTime(0.0001,t+.2);
282	  o.connect(g);g.connect(masterGain);o.start(t);o.stop(t+.22);
283	}
284	
285	document.getElementById('mute').onclick=function(){
286	  muted=!muted;
287	  this.textContent=muted?'🔕':'🔔';
288	  if(AC){
289	    masterGain.gain.setValueAtTime(muted?0:1,AC.currentTime);
290	    if(!muted&&!droneNode)startDrone();
291	  }
292	};
293	
294	/* ══════════ 工具效果 ══════════ */
295	function equippedHand(){return W&&W.equipped&&W.equipped.hand||null;}
296	function checkHarvest(resKind){
297	  const tool=equippedHand();
298	  if(resKind==='stone'){
299	    if(!tool||(!tool.includes('pick'))){return{ok:true,mul:0.5,bare:true};}
300	    const mul=tool==='iron_pick'?2:1;
301	    return{ok:true,mul};
302	  }
303	  if(resKind==='clay'){
304	    const mul={stone_pick:1.5,iron_pick:2}[tool]||1;
305	    return{ok:true,mul};
306	  }
307	  if(resKind==='wood'){
308	    const mul={wooden_axe:2,stone_axe:3,iron_axe:5}[tool]||1;
309	    return{ok:true,mul};
310	  }
311	  return{ok:true,mul:1};
312	}
313	
314	/* ══════════ 地圖生成工具 / 任務 → lib/worldgen.js + lib/data.js ══════════ */
315	
316	/* ══════════ 建造清單 ══════════ */
317	function grassy(t){return t===T.GRASS||t===T.MEADOW||t===T.FOREST;}
318	function landEmpty(i){const t=W.ter[i];return(t>=T.SAND&&t<=T.ROCKY||t===T.PATH)&&t!==T.WATER&&W.obj[i]===O.NONE;}
319	
320	const BUILDS=[
321	  {sec:'建築'},
322	  {id:'fire',ico:'🔥',name:'營火',desc:'夜間照明,互動可休息到清晨',cost:{wood:5},
323	   place(x,y,i){if(!landEmpty(i))return 0;W.obj[i]=O.FIRE;W.stats.fires++;return 1;}},
324	  {id:'hut', ico:'🏠',name:'小屋',desc:'溫暖的家,互動可休息到清晨',cost:{wood:20,stone:8,fiber:4},
325	   place(x,y,i){if(!landEmpty(i))return 0;W.obj[i]=O.HUT;W.stats.huts++;return 1;}},
326	  {id:'farm',ico:'🟫',name:'農田',desc:'翻土開墾,之後帶種子互動播種',cost:{wood:2},
327	   place(x,y,i){if(!(grassy(W.ter[i])&&W.obj[i]===O.NONE))return 0;W.ter[i]=T.FARM;return 1;}},
328	  {id:'workbench',ico:'🪚',name:'工作臺',desc:'解鎖進階製作:服裝·工具·石斧',cost:{wood:8,stone:3},
329	   place(x,y,i){if(!landEmpty(i))return 0;W.obj[i]=O.WORKBENCH;W.stats.workbenches++;return 1;}},
330	  {id:'loom',ico:'🧵',name:'織布機',desc:'高效率織布,解鎖羊毛大衣配方',cost:{wood:10,fiber:6},
331	   need:()=>(W.stats.workbenches||0)>=1,needMsg:'需要先建好工作臺',
332	   place(x,y,i){if(!landEmpty(i))return 0;W.obj[i]=O.LOOM;return 1;}},
333	  {id:'forge',ico:'⚒️',name:'鍛造爐',desc:'冶煉鐵錠·打造鐵製工具',cost:{stone:15,clay:5,wood:5},
334	   need:()=>(W.stats.workbenches||0)>=1,needMsg:'需要先建好工作臺',
335	   place(x,y,i){if(!landEmpty(i))return 0;W.obj[i]=O.FORGE;return 1;}},
336	  {id:'well',ico:'⛲',name:'水井',desc:'加速周圍 3 格作物生長',cost:{stone:8,clay:2},
337	   place(x,y,i){if(!landEmpty(i))return 0;W.obj[i]=O.WELL;return 1;}},
338	  {id:'monu',ico:'🏛️',name:'紀念碑',desc:'先民的高塔。需要 3 張古老圖紙',cost:{wood:25,stone:30,relic:3},
339	   need:()=>W.inv.relic>=3,needMsg:'需要集齊 3 張古老圖紙',
340	   place(x,y,i){if(!landEmpty(i))return 0;W.obj[i]=O.MONU;W.stats.monu++;return 1;}},
341	  {sec:'道路與地形'},
342	  {id:'bridge',ico:'🪜',name:'木橋',desc:'鋪在淺水上,可以通行',cost:{wood:4,fiber:1},
343	   place(x,y,i){if(!(W.ter[i]===T.WATER&&W.obj[i]===O.NONE))return 0;W.ter[i]=T.BRIDGE;W.stats.bridges++;return 1;}},
344	  {id:'path',ico:'🟨',name:'石板路',desc:'走在上面移動更快',cost:{stone:2},
345	   place(x,y,i){if(!(W.ter[i]>=T.SAND&&W.ter[i]<=T.ROCKY&&W.ter[i]!==T.WATER&&W.obj[i]===O.NONE))return 0;W.ter[i]=T.PATH;return 1;}},
346	  {id:'fill',ico:'⛰️',name:'填土造地',desc:'把淺水填成沙地',cost:{stone:3},
347	   place(x,y,i){if(!(W.ter[i]===T.WATER&&W.obj[i]===O.NONE))return 0;W.ter[i]=T.SAND;return 1;}},
348	  {id:'pond',ico:'💧',name:'挖掘池塘',desc:'挖成水塘,順便得到黏土',cost:{},stamCost:10,
349	   place(x,y,i){if(!(grassy(W.ter[i])&&W.obj[i]===O.NONE))return 0;W.ter[i]=T.WATER;W.inv.clay+=1;return 1;}},
350	  {sec:'種植'},
351	  {id:'plant',ico:'🌱',name:'種植樹苗',desc:'幾天後長成大樹',cost:{sap:1},
352	   place(x,y,i){if(!(grassy(W.ter[i])&&W.obj[i]===O.NONE))return 0;W.obj[i]=O.SAPLING;W.aux[i]=0;return 1;}},
353	];
