355	/* ══════════ 全域狀態 ══════════ */
356	let W=null,running=false;
357	const cv=document.getElementById('game'),ctx=cv.getContext('2d');
358	const mm=document.getElementById('minimap'),mctx=mm.getContext('2d');
359	let vw=0,vh=0,dpr=1;
360	function resize(){dpr=Math.min(window.devicePixelRatio||1,2);vw=window.innerWidth;vh=window.innerHeight;cv.width=vw*dpr;cv.height=vh*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);}
361	window.addEventListener('resize',resize);resize();
362	
363	/* ══════════ UI:提示與 Toast ══════════ */
364	const toastsEl=document.getElementById('toasts');
365	function toast(msg,quest){
366	  const d=document.createElement('div');d.className='toast'+(quest?' quest':'');d.textContent=msg;
367	  toastsEl.appendChild(d);
368	  if(toastsEl.children.length>4)toastsEl.firstChild.remove();
369	  setTimeout(()=>d.remove(),3200);
370	}
371	
372	function checkQuest(){
373	  let adv=false;
374	  while(W.questIdx<QUESTS.length){
375	    const q=QUESTS[W.questIdx];
376	    if(q.c(W.stats,W)){toast('📖 手帳:「'+q.t+'」完成!',true);W.questIdx++;adv=true;}
377	    else break;
378	  }
379	  if(adv){sfx('quest');renderQuests();}
380	}
381	
382	/* ══════════ UI:庫存 HUD ══════════ */
383	const invBarEl=document.getElementById('invbar');
384	function renderInv(){
385	  invBarEl.innerHTML='';
386	  for(const [k,r] of Object.entries(RESOURCES)){
387	    const v=W.inv[k];
388	    if(v<=0&&!r.alwaysShow)continue;
389	    const d=document.createElement('div');d.className='slot';
