};

/* ══════════ 工具效果 ══════════ */
function equippedHand(){return W&&W.equipped&&W.equipped.hand||null;}
function checkHarvest(resKind){
  const tool=equippedHand();
  if(resKind==='stone'){
    if(!tool||(!tool.includes('pick'))){return{ok:true,mul:0.5,bare:true};}
    const mul=tool==='iron_pick'?2:1;
    return{ok:true,mul};
  }
  if(resKind==='clay'){
    const mul={stone_pick:1.5,iron_pick:2}[tool]||1;
    return{ok:true,mul};
  }
  if(resKind==='wood'){
    const mul={wooden_axe:2,stone_axe:3,iron_axe:5}[tool]||1;
    return{ok:true,mul};
  }
  return{ok:true,mul:1};
}

