646	function updateAnimals(dt){
647	  for(const a of W.animals){
648	    // 資源計時
649	    if(a.state==='tamed'&&a.resourceTimer>0)a.resourceTimer-=dt;
650	    // 逃跑計時
651	    if(a.fleeTimer>0){a.fleeTimer-=dt;if(a.fleeTimer<=0&&a.state==='fleeing'){a.state='wild';a.vx=0;a.vy=0;}}
652	    // 行為
653	    if(a.state==='wild'){
654	      const dist=Math.hypot(a.x-W.px,a.y-W.py);
655	      if(dist<2.5){
656	        const ang=Math.atan2(a.y-W.py,a.x-W.px);
657	        a.vx=Math.cos(ang)*2.8;a.vy=Math.sin(ang)*2.8;
658	        a.state='fleeing';a.fleeTimer=2.5;
659	      }else if(a.state!=='fleeing'&&Math.random()<dt*0.4){
660	        const ang=Math.random()*Math.PI*2;
661	        a.vx=Math.cos(ang)*0.5;a.vy=Math.sin(ang)*0.5;
662	      }
663	    }else if(a.state==='tamed'){
664	      const dist=Math.hypot(a.x-W.px,a.y-W.py);
665	      if(dist>5){
666	        const ang=Math.atan2(W.py-a.y,W.px-a.x);
667	        a.vx=Math.cos(ang)*0.8;a.vy=Math.sin(ang)*0.8;
668	      }else if(dist<0.5){
669	        const ang=Math.atan2(a.y-W.py,a.x-W.px)||0;
670	        a.vx=Math.cos(ang)*0.3;a.vy=Math.sin(ang)*0.3;
671	      }else if(Math.random()<dt*0.3){
672	        const ang=Math.random()*Math.PI*2;a.vx=Math.cos(ang)*0.2;a.vy=Math.sin(ang)*0.2;
673	      }
674	      // 動物間互斥：太近就互相推開
675	      for(const b of W.animals){
676	        if(b===a)continue;
677	        const sep=Math.hypot(a.x-b.x,a.y-b.y);
678	        if(sep<1.2&&sep>0){
