function tryMove(d){
  W.face=d;if(moveCd>0)return;
  const nx=W.px+DX[d],ny=W.py+DY[d];
  if(nx<0||ny<0||nx>=SIZE||ny>=SIZE)return;
  const i=ny*SIZE+nx,t=W.ter[i],o=W.obj[i];
  if(t===T.DEEP||t===T.WATER||t===T.MTN)return;
  if([O.TREE,O.ROCK,O.RUIN,O.FIRE,O.HUT,O.WELL,O.MONU,O.SAPLING,O.CROP,O.WORKBENCH,O.LOOM,O.FORGE].includes(o))return;
  W.px=nx;W.py=ny;
  const speedMul=W.equipped.feet==='boots'?0.65:1;
  moveCd=((t===T.PATH||t===T.BRIDGE)?0.16:0.25)*speedMul;
  discover();
}

