/* ══════════ 敵人系統 ══════════ */
function nearestEnemy(){
  const f=faceTile();if(!f)return null;
  for(const e of (W.enemies||[])){
    if(e.hp<=0)continue;
    if(Math.abs(e.x-f.x)<1.3&&Math.abs(e.y-f.y)<1.3)return e;
  }
  return null;
}

function enemyAction(e){
  const def=ENEMY_DEF[e.kind];
  const wpn=equippedWeapon();
  const atk=3+(wpn&&EQUIP_DEF[wpn]?EQUIP_DEF[wpn].atk||0:0);
  const dmg=Math.max(1,atk+Math.floor(Math.random()*3)-1);
  return{label:'攻擊'+def.name+' (ATK ~'+atk+')',run(){
    if(wpn)wearEquip('weapon',1);
    e.hp-=dmg;spawnFloat(e.x,e.y,'-'+dmg);sfx('pick');
    if(e.hp<=0){
      e.hp=0;
      for(const drop of def.loot){if(Math.random()<drop.p)gain(drop.k,drop.n,{x:Math.floor(e.x),y:Math.floor(e.y)});}
      toast(def.ico+' '+def.name+'被打倒了!');sfx('quest');
    }else{
      toast(def.ico+' '+def.name+' HP:'+e.hp+'/'+e.maxHp);
      const pdmg=Math.max(1,def.atk+Math.floor(Math.random()*2)-1);
      W.hp=Math.max(0,W.hp-pdmg);spawnFloat(W.px,W.py,'💔-'+pdmg);sfx('no');
      if(W.hp<=0)playerDeath();else updateHUD();
    }
  },stam:0};
}

function updateEnemies(dt){
  for(const e of (W.enemies||[])){
    if(e.hp<=0)continue;
    const dist=Math.hypot(e.x-W.px,e.y-W.py);
    const def=ENEMY_DEF[e.kind];
    if(dist<7){e.state='chase';e.alertTimer=3;}
    else if(e.alertTimer>0){e.alertTimer-=dt;if(e.alertTimer<=0)e.state='idle';}
    if(e.state==='chase'){
      const ang=Math.atan2(W.py-e.y,W.px-e.x);
      e.vx=Math.cos(ang)*def.spd;e.vy=Math.sin(ang)*def.spd;
      e.attackTimer=(e.attackTimer||0)-dt;
      if(dist<1.1&&e.attackTimer<=0){
        const pdmg=Math.max(1,def.atk+Math.floor(Math.random()*2)-1);
        W.hp=Math.max(0,W.hp-pdmg);e.attackTimer=1.8;
        spawnFloat(W.px,W.py,'💔-'+pdmg);sfx('no');
        if(W.hp<=0)playerDeath();else updateHUD();
      }
    }else if(Math.random()<dt*0.25){
      const ang=Math.random()*Math.PI*2;
      e.vx=Math.cos(ang)*def.spd*.3;e.vy=Math.sin(ang)*def.spd*.3;
    }
    const nx=e.x+e.vx*dt,ny=e.y+e.vy*dt;
    const ti=Math.floor(ny)*SIZE+Math.floor(nx);
    if(Math.floor(nx)>=1&&Math.floor(ny)>=1&&Math.floor(nx)<SIZE-1&&Math.floor(ny)<SIZE-1
      &&W.ter[ti]===T.ROCKY&&W.obj[ti]===O.NONE)
      {e.x=clamp(nx,.5,SIZE-.5);e.y=clamp(ny,.5,SIZE-.5);}
    else{e.vx=0;e.vy=0;}
    e.vx*=.88;e.vy*=.88;
  }
}

function drawEnemy(e){
  if(e.hp<=0)return;
  const sx=Math.round(e.x*TS-camX),sy=Math.round(e.y*TS-camY);
  if(sx<-TS||sy<-TS||sx>vw+TS||sy>vh+TS)return;
  const cx=sx,cy=sy-6;
  ctx.fillStyle='rgba(0,0,0,.2)';ctx.beginPath();ctx.ellipse(cx,sy+6,8,3,0,0,Math.PI*2);ctx.fill();
  if(e.kind==='gopher'){
    ctx.fillStyle='#7a4a20';ctx.beginPath();ctx.ellipse(cx,cy+2,7,8,0,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#e8b080';ctx.beginPath();ctx.ellipse(cx,cy+4,4,5,0,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#201010';circle(cx-2.5,cy,1.5);circle(cx+2.5,cy,1.5);
    ctx.strokeStyle='#6a3a15';ctx.lineWidth=1.5;
    ctx.beginPath();ctx.moveTo(cx-8,cy+7);ctx.lineTo(cx-5,cy+10);ctx.stroke();
    ctx.beginPath();ctx.moveTo(cx+8,cy+7);ctx.lineTo(cx+5,cy+10);ctx.stroke();
  }else if(e.kind==='stone_crab'){
    ctx.fillStyle='#6a7a5a';ctx.beginPath();ctx.ellipse(cx,cy+3,10,7,0,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#5a6a4a';ctx.beginPath();ctx.arc(cx-12,cy,5,0,Math.PI*2);ctx.fill();
    ctx.beginPath();ctx.arc(cx+12,cy,5,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#e84040';circle(cx-4,cy-3,2);circle(cx+4,cy-3,2);
  }else{
    ctx.fillStyle='#e8e8e0';ctx.beginPath();ctx.arc(cx,cy-8,7,0,Math.PI*2);ctx.fill();
    ctx.strokeStyle='#e8e8e0';ctx.lineWidth=2;
    ctx.beginPath();ctx.moveTo(cx,cy);ctx.lineTo(cx,cy+12);ctx.stroke();
    ctx.beginPath();ctx.moveTo(cx-6,cy+4);ctx.lineTo(cx+6,cy+4);ctx.stroke();
    ctx.beginPath();ctx.moveTo(cx,cy+12);ctx.lineTo(cx-4,cy+20);ctx.moveTo(cx,cy+12);ctx.lineTo(cx+4,cy+20);ctx.stroke();
    ctx.fillStyle='#2a2a20';circle(cx-2.5,cy-9,2);circle(cx+2.5,cy-9,2);
    ctx.strokeStyle='#c0c0b0';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(cx+8,cy+2);ctx.lineTo(cx+14,cy-8);ctx.stroke();
  }
  // HP bar
  const bw=20,hr=e.hp/e.maxHp;
  ctx.fillStyle='#400';ctx.fillRect(cx-bw/2,sy-TS/2-6,bw,4);
  ctx.fillStyle=hr>0.5?'#6b6':'#c44';ctx.fillRect(cx-bw/2,sy-TS/2-6,Math.round(bw*hr),4);
  if(e.state==='chase'){ctx.fillStyle='#e84040';ctx.font='700 9px sans-serif';ctx.textAlign='center';ctx.fillText('!',cx,cy-14);}
}

/* ══════════ 死亡 / 地城 ══════════ */
function collectDeathItems(){
  if(!W.deathItems)return;
  for(const [k,n] of Object.entries(W.deathItems))if(n>0)W.inv[k]=(W.inv[k]||0)+n;
  if(W.deathPos){const gi=W.deathPos.y*SIZE+W.deathPos.x;if(W.obj[gi]===O.GRAVE)W.obj[gi]=O.NONE;}
  W.deathItems=null;W.deathPos=null;mmDirty=true;
  toast('✅ 取回了所有遺落物品!');sfx('quest');renderInv();renderBagPanel();
}

let _dying=false;
function playerDeath(){
  if(_dying)return;_dying=true;
  // 收集所有物品
  const items={};
  for(const k of Object.keys(W.inv))items[k]=(items[k]||0)+(W.inv[k]||0);
  for(const [slot,eq] of Object.entries(W.equipped)){if(eq)items[eq]=(items[eq]||0)+1;}
  W.deathItems=items;
  // 死亡點 (在地面)
  const gx=W.inDungeon&&W._surface?W._surface.px:W.px;
  const gy=W.inDungeon&&W._surface?W._surface.py:W.py;
  W.deathPos={x:gx,y:gy};
  if(W.inDungeon&&W._surface)W._surface.obj[gy*SIZE+gx]=O.GRAVE;
  else W.obj[gy*SIZE+gx]=O.GRAVE;
  mmDirty=true;
  // 清空物品與裝備
  for(const k of Object.keys(W.inv))W.inv[k]=0;
  W.equipped={head:null,body:null,hand:null,hands:null,feet:null,weapon:null};
  W.equipDur={head:null,body:null,hand:null,hands:null,feet:null,weapon:null};
  W.hp=Math.round(W.maxHp/2);
  sfx('no');
  const fade=document.getElementById('fade');fade.style.opacity=1;
  setTimeout(()=>{
    if(W.inDungeon&&W._surface){
      const s=W._surface;
      W.ter=s.ter;W.obj=s.obj;W.aux=s.aux;W.disc=s.disc;
      W.px=s.px;W.py=s.py;W.enemies=s.enemies||[];
      W._surface=null;W.inDungeon=false;W.dungeonIdx=-1;W.dungeonFloor=0;
      document.getElementById('depthCard').style.display='none';
    }
    camInit=false;mmDirty=true;discover();updateHUD();renderInv();renderBagPanel();
    toast('💀 你倒下了…物品已遺落，找 🪦 墓碑可取回。');
    fade.style.opacity=0;_dying=false;
  },800);
}

function genChestLoot(floor){
  const loot=[];
  const roll=(k,n,p)=>{if(Math.random()<p)loot.push({k,n});};
  roll('food',   2+Math.floor(Math.random()*3), 0.9);
  roll('stone',  3+Math.floor(Math.random()*4), 0.7);
  roll('coal',   1+Math.floor(Math.random()*2), floor>=2?0.6:0.2);
  roll('iron_ore',1+Math.floor(Math.random()*3),floor>=2?0.5:0.1);
  roll('iron_ingot',1+Math.floor(Math.random()*2),floor>=3?0.4:0);
  roll('relic',  1, floor>=4?0.4:0);
  if(!loot.length)loot.push({k:'food',n:2});
  return loot;
}

function enterDungeon(ruinIdx){
  if(W.inDungeon)return;
  const fade=document.getElementById('fade');fade.style.opacity=1;
  setTimeout(()=>{
    W._surface={ter:W.ter,obj:W.obj,aux:W.aux,disc:W.disc,px:W.px,py:W.py,enemies:W.enemies||[]};
    const key=ruinIdx+'_1';
    if(!W.dungeons[key])W.dungeons[key]=genDungeon(W.seedStr,ruinIdx,1);
    const d=W.dungeons[key];
    W.ter=d.ter;W.obj=d.obj;W.aux=d.aux;W.disc=d.disc;
    W.enemies=d.enemies.map(e=>({...e}));
    W.px=d.spawnX;W.py=d.spawnY;
    W.inDungeon=true;W.dungeonIdx=ruinIdx;W.dungeonFloor=1;W.face=0;
    camInit=false;mmDirty=true;discover();updateHUD();
    toast('🪨 B1 地城 — 小心怪物!');
    fade.style.opacity=0;
  },650);
}
function exitDungeon(){
  if(!W.inDungeon||!W._surface)return;
  const fade=document.getElementById('fade');fade.style.opacity=1;
  setTimeout(()=>{
    W.dungeons[W.dungeonIdx+'_'+W.dungeonFloor]={ter:W.ter,obj:W.obj,aux:W.aux,disc:W.disc,enemies:W.enemies,spawnX:W.px,spawnY:W.py};
    const s=W._surface;
    W.ter=s.ter;W.obj=s.obj;W.aux=s.aux;W.disc=s.disc;
    W.px=s.px;W.py=s.py;W.enemies=s.enemies||[];
    W._surface=null;W.inDungeon=false;W.dungeonIdx=-1;W.dungeonFloor=0;W.face=1;
    camInit=false;mmDirty=true;discover();updateHUD();
    toast('☀️ 回到地面了');
    document.getElementById('depthCard').style.display='none';
    fade.style.opacity=0;
  },650);
}
function goDownstairs(){
  if(!W.inDungeon||W.dungeonFloor>=4){toast('這已經是最深層了');return;}
  const nextFloor=W.dungeonFloor+1;
  const fade=document.getElementById('fade');fade.style.opacity=1;
  setTimeout(()=>{
    W.dungeons[W.dungeonIdx+'_'+W.dungeonFloor]={ter:W.ter,obj:W.obj,aux:W.aux,disc:W.disc,enemies:W.enemies,spawnX:W.px,spawnY:W.py};
    const key=W.dungeonIdx+'_'+nextFloor;
    if(!W.dungeons[key])W.dungeons[key]=genDungeon(W.seedStr,W.dungeonIdx,nextFloor);
    const d=W.dungeons[key];
    W.ter=d.ter;W.obj=d.obj;W.aux=d.aux;W.disc=d.disc;
    W.enemies=d.enemies.map(e=>({...e}));
    W.px=d.spawnX;W.py=d.spawnY;W.dungeonFloor=nextFloor;W.face=0;
    camInit=false;mmDirty=true;discover();updateHUD();
