    toast('🪨 B1 地城 — 小心怪物!');
    fade.style.opacity=0;
  },650);
}
function exitDungeon(){
  if(!W.inDungeon||!W._surface)return;
  const fade=document.getElementById('fade');fade.style.opacity=1;
  setTimeout(()=>{
    W.dungeons[W.dungeonIdx+'_'+W.dungeonFloor]={ter:W.ter,obj:W.obj,aux:W.aux,disc:W.disc,enemies:W.enemies,spawnX:W.px,spawnY:W.py};
