      }
    }
  }

  /* ── 寶箱（跳過第一間，數量隨層遞增）── */
  const chestCount=Math.min(carved.length-1,1+Math.floor(floor/2));
  for(let ci=0;ci<chestCount;ci++){
    const r=carved[1+ci];
