      const cx=r.x+1+Math.floor(rng()*(r.w-2));
      const cy=r.y+1+Math.floor(rng()*(r.h-2));
      if(ter[cy*SIZE+cx]===T.ROCKY&&obj[cy*SIZE+cx]===O.NONE){obj[cy*SIZE+cx]=O.CHEST;placed=true;}
