function goDownstairs(){
  if(!W.inDungeon||W.dungeonFloor>=4){toast('這已經是最深層了');return;}
  if(_transitioning)return;_transitioning=true;
  const nextFloor=W.dungeonFloor+1;
  const fade=document.getElementById('fade');fade.style.opacity=1;
  setTimeout(()=>{
    W.dungeons[W.dungeonIdx+'_'+W.dungeonFloor]={ter:W.ter,obj:W.obj,aux:W.aux,disc:W.disc,enemies:W.enemies,spawnX:W.px,spawnY:W.py};
    const key=W.dungeonIdx+'_'+nextFloor;
    if(!W.dungeons[key])W.dungeons[key]=genDungeon(W.seedStr,W.dungeonIdx,nextFloor);
    const d=W.dungeons[key];
    W.ter=d.ter;W.obj=d.obj;W.aux=d.aux;W.disc=d.disc;
    W.enemies=d.enemies.map(e=>({...e}));
    W.px=d.spawnX;W.py=d.spawnY;W.dungeonFloor=nextFloor;W.face=0;
    camInit=false;mmDirty=true;discover();updateHUD();
    toast('🪨 B'+W.dungeonFloor+(nextFloor===4?' — 最深層!':' — 往更深處…'));
    fade.style.opacity=0;_transitioning=false;
  },650);
}
function goUpstairs(){
  if(!W.inDungeon)return;
  if(W.dungeonFloor<=1){exitDungeon();return;}
  if(_transitioning)return;_transitioning=true;
  const prevFloor=W.dungeonFloor-1;
  const fade=document.getElementById('fade');fade.style.opacity=1;
  setTimeout(()=>{
    W.dungeons[W.dungeonIdx+'_'+W.dungeonFloor]={ter:W.ter,obj:W.obj,aux:W.aux,disc:W.disc,enemies:W.enemies,spawnX:W.px,spawnY:W.py};
    const key=W.dungeonIdx+'_'+prevFloor;
    if(!W.dungeons[key])W.dungeons[key]=genDungeon(W.seedStr,W.dungeonIdx,prevFloor);
    const d=W.dungeons[key];
    W.ter=d.ter;W.obj=d.obj;W.aux=d.aux;W.disc=d.disc;
    W.enemies=d.enemies.map(e=>({...e}));
    W.px=d.spawnX;W.py=d.spawnY;W.dungeonFloor=prevFloor;W.face=0;
    camInit=false;mmDirty=true;discover();updateHUD();
    toast('🪨 B'+W.dungeonFloor);
    fade.style.opacity=0;_transitioning=false;
  },650);
}

function cropStage(i){return Math.min(2,Math.floor(W.aux[i]));}
function nearWell(x,y){for(let dy=-3;dy<=3;dy++)for(let dx=-3;dx<=3;dx++){const nx=x+dx,ny=y+dy;if(nx<0||ny<0||nx>=SIZE||ny>=SIZE)continue;if(W.obj[ny*SIZE+nx]===O.WELL)return true;}return false;}

