  const stItems=allR.filter(k=>st[k]>0);
  if(!stItems.length){const em=document.createElement('div');em.style.cssText='color:#aaa;font-size:12px;padding:4px 0 8px';em.textContent='（空的）';el.appendChild(em);}
  for(const rk of stItems){
    const row=document.createElement('div');
    row.style.cssText='display:flex;align-items:center;gap:8px;margin-bottom:4px;';
    const res=RESOURCES[rk];
    row.innerHTML=`<span style="width:22px;text-align:center">${res.ico}</span><span style="flex:1">${res.name}</span><b>${st[rk]}</b>`;
    const btn=document.createElement('button');btn.className='rmake st-btn';btn.textContent='取出';
    btn.onclick=()=>{W.inv[rk]=(W.inv[rk]||0)+(st[rk]||0);delete st[rk];renderStoragePanel();renderInv();};
    row.appendChild(btn);el.appendChild(row);
  }
  // 分隔
  const sep=document.createElement('hr');sep.style.margin='8px 0';el.appendChild(sep);
  const ih=document.createElement('div');
  ih.style.cssText='font-weight:800;margin-bottom:6px;color:var(--ink)';ih.textContent='🎒 背包（點存入）';
  el.appendChild(ih);
  const invItems=allR.filter(rk=>(W.inv[rk]||0)>0);
  if(!invItems.length){const em=document.createElement('div');em.style.cssText='color:#aaa;font-size:12px;padding:4px 0';em.textContent='（背包是空的）';el.appendChild(em);}
  for(const rk of invItems){
    const row=document.createElement('div');
    row.style.cssText='display:flex;align-items:center;gap:8px;margin-bottom:4px;';
    const res=RESOURCES[rk];
    row.innerHTML=`<span style="width:22px;text-align:center">${res.ico}</span><span style="flex:1">${res.name}</span><b>${W.inv[rk]}</b>`;
    const btn=document.createElement('button');btn.className='rmake st-btn';btn.textContent='存入';
    btn.style.background='#4a7a38';
    btn.onclick=()=>{st[rk]=(st[rk]||0)+(W.inv[rk]||0);W.inv[rk]=0;renderStoragePanel();renderInv();};
    row.appendChild(btn);el.appendChild(row);
  }
}

